from __future__ import annotations
from typing import Annotated, Any, Literal
from pydantic import BaseModel, ConfigDict, Field, RootModel
from datetime import date


class CrawlRequest(BaseModel):
    model_config = ConfigDict(
        populate_by_name=True,
    )
    url: Annotated[
        str,
        Field(
            description="The root URL to begin the crawl.", examples=["docs.tavily.com"]
        ),
    ]
    instructions: Annotated[
        str | None,
        Field(
            description="Natural language instructions for the crawler. When specified, the mapping cost increases to 2 API credits per 10 successful pages instead of 1 API credit per 10 pages.",
            examples=["Find all pages about the Python SDK"],
        ),
    ] = None
    chunks_per_source: Annotated[
        int | None,
        Field(
            description="Chunks are short content snippets (about 800 characters each) pulled directly from the source. Use `chunks_per_source` to define the maximum number of relevant chunks returned per source and to control the `raw_content` length. Chunks will appear in the `raw_content` field as: `<chunk 1> [...] <chunk 2> [...] <chunk 3>`. If a page splits into no more chunks than `chunks_per_source`, its full content is returned. Available only when `instructions` are provided. Must be between 1 and 5.",
            ge=1,
            le=5,
        ),
    ] = 3
    max_depth: Annotated[
        int | None,
        Field(
            description="Max depth of the crawl. Defines how far from the base URL the crawler can explore.",
            ge=1,
            le=5,
        ),
    ] = 1
    max_breadth: Annotated[
        int | None,
        Field(
            description="Max number of links to follow per level of the tree (i.e., per page).",
            ge=1,
            le=500,
        ),
    ] = 20
    limit: Annotated[
        int | None,
        Field(
            description="Total number of links the crawler will process before stopping.",
            ge=1,
        ),
    ] = 50
    select_paths: Annotated[
        list[str] | None,
        Field(
            description="Regex patterns to select only URLs with specific path patterns (e.g., `/docs/.*`, `/api/v1.*`)."
        ),
    ] = None
    select_domains: Annotated[
        list[str] | None,
        Field(
            description="Regex patterns to select crawling to specific domains or subdomains (e.g., `^docs\\.example\\.com$`)."
        ),
    ] = None
    exclude_paths: Annotated[
        list[str] | None,
        Field(
            description="Regex patterns to exclude URLs with specific path patterns (e.g., `/private/.*`, `/admin/.*`)."
        ),
    ] = None
    exclude_domains: Annotated[
        list[str] | None,
        Field(
            description="Regex patterns to exclude specific domains or subdomains from crawling (e.g., `^private\\.example\\.com$`)."
        ),
    ] = None
    allow_external: Annotated[
        bool | None,
        Field(
            description="Whether to include external domain links in the final results list."
        ),
    ] = True
    include_images: Annotated[
        bool | None,
        Field(description="Whether to include images in the crawl results."),
    ] = False
    extract_depth: Annotated[
        Literal["basic", "advanced"] | None,
        Field(
            description="Advanced extraction retrieves more data, including tables and embedded content, with higher success but may increase latency. `basic` extraction costs 1 credit per 5 successful extractions, while `advanced` extraction costs 2 credits per 5 successful extractions."
        ),
    ] = "basic"
    format: Annotated[
        Literal["markdown", "text"] | None,
        Field(
            description="The format of the extracted web page content. `markdown` returns content in markdown format. `text` returns plain text and may increase latency."
        ),
    ] = "markdown"
    include_favicon: Annotated[
        bool | None,
        Field(description="Whether to include the favicon URL for each result."),
    ] = False
    timeout: Annotated[
        float | None,
        Field(
            description="Maximum time in seconds to wait for the crawl operation before timing out. Must be between 10 and 150 seconds.",
            ge=10.0,
            le=150.0,
        ),
    ] = 150
    include_usage: Annotated[
        bool | None,
        Field(
            description="Whether to include credit usage information in the response. `NOTE:`The value may be 0 if the total use of /extract and /map have not yet reached minimum requirements. See our [Credits & Pricing documentation](https://docs.tavily.com/documentation/api-credits) for details."
        ),
    ] = False


class Result(BaseModel):
    model_config = ConfigDict(
        populate_by_name=True,
    )
    url: Annotated[
        str | None,
        Field(
            description="The URL that was crawled.",
            examples=["https://docs.tavily.com"],
        ),
    ] = None
    raw_content: Annotated[
        str | None,
        Field(
            description="The full content extracted from the page. When `query` is provided, contains the top-ranked chunks joined by `[...]` separator."
        ),
    ] = None
    favicon: Annotated[
        str | None,
        Field(
            description="The favicon URL for the result.",
            examples=[
                "https://mintlify.s3-us-west-1.amazonaws.com/tavilyai/_generated/favicon/apple-touch-icon.png?v=3"
            ],
        ),
    ] = None


