# --- operations (belt) ---------------------------------------------------------

from typing import Any, Dict, Optional

from inferencesh import BaseAppInput, BaseAppOutput, OutputMeta
from inferencesh.upstream import Auth, Operation
from pydantic import Field

BASE_URL = "https://api.tavily.com"
CREDENTIAL = "tavily"
AUTH = {
    "bearerAuth": Auth(kind="http", scheme="bearer", secret="TVLY_API_KEY"),
}
DEFAULT_AUTH = "bearerAuth"


# --- crawl: POST /crawl

crawl = Operation(
    name="crawl",
    method="POST",
    path="/crawl",
    body="json",
    annotations={"title": "Initiate a web crawl from a base URL", "readOnlyHint": False, "destructiveHint": False, "idempotentHint": False, "openWorldHint": True},
    credentials=None,
    summary="Initiate a web crawl from a base URL",
)


class CrawlInput(BaseAppInput, CrawlRequest):
    pass


class CrawlOutput(BaseAppOutput, CrawlResponse):
    raw: Any = Field(default=None, description="The vendor's response, unchanged.")

    @classmethod
    def from_response(cls, data: Any, output_meta: Optional[OutputMeta] = None) -> "CrawlOutput":
        body = data if isinstance(data, dict) else {}
        return cls.model_validate({**body, "raw": data, "output_meta": output_meta})


